import unittest
from candidate import factorize

class TestFactorize(unittest.TestCase):
    def test_factorize_normal_case(self):
        self.assertEqual(factorize(8), [2, 2, 2])

    def test_factorize_prime_number(self):
        self.assertEqual(factorize(7), [7])

    def test_factorize_perfect_square(self):
        self.assertEqual(factorize(16), [2, 2, 2, 2])

    def test_factorize_square_root(self):
        self.assertEqual(factorize(9), [3, 3])

    def test_factorize_larger_number(self):
        self.assertEqual(factorize(70), [2, 5, 7])

    def test_factorize_even_number(self):
        self.assertEqual(factorize(12), [2, 2, 3])

    def test_factorize_smallest_prime(self):
        self.assertEqual(factorize(2), [2])

    def test_factorize_negative_number(self):
        self.assertEqual(factorize(-8), [2, 2, 2])

    def test_factorize_zero(self):
        self.assertEqual(factorize(0), [])

    def test_factorize_large_even_number(self):
        self.assertEqual(factorize(100), [2, 2, 5, 5])

    def test_factorize_large_odd_number(self):
        self.assertEqual(factorize(101), [101])

    def test_factorize_edge_case_sqrt_plus_one(self):
        self.assertEqual(factorize(11), [11])

if __name__ == '__main__':
    unittest.main()
